请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-006

=== 用户原始指令 (query.txt) ===
列一排能关的东西，按一下能开省电模式

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "列一排能关的东西，按一下能开省电模式",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModelSchema": {
    "mode": {
      "title": {
        "type": "string",
        "description": "低电模式卡片标题",
        "sampleValue": "低电模式"
      },
      "status": {
        "type": "string",
        "description": "省电模式当前建议状态",
        "sampleValue": "建议开启"
      },
      "summary": {
        "type": "string",
        "description": "可关闭项目的简短提示",
        "sampleValue": "先关高耗电项"
      },
      "actionLabel": {
        "type": "string",
        "description": "开启省电模式的动作文案",
        "sampleValue": "开启省电"
      }
    },
    "items": [
      {
        "label": {
          "type": "string",
          "description": "第一个可关闭项目名称",
          "sampleValue": "亮度"
        }
      },
      {
        "label": {
          "type": "string",
          "description": "第二个可关闭项目名称",
          "sampleValue": "定位"
        }
      },
      {
        "label": {
          "type": "string",
          "description": "第三个可关闭项目名称",
          "sampleValue": "蓝牙"
        }
      }
    ],
    "asset": {
      "icon": {
        "type": "string",
        "description": "低电模式省电图标素材路径",
        "sampleValue": "resources/base/media/icon_save_power.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电图标，适合表达低电模式或开启省电动作。",
      "bindTo": "/asset/icon"
    }
  ]
}

